import React, { useEffect, useState } from 'react';
import { getWorkflows } from '../services/workflowService';
import { toast } from 'react-toastify';

const WorkflowManagement = () => {
  const [workflows, setWorkflows] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadWorkflows = async () => {
    try {
      const data = await getWorkflows();
      setWorkflows(Array.isArray(data) ? data : []);
    } catch (error) {
      toast.error('Erreur lors du chargement des workflows');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadWorkflows();
  }, []);

  return (
    <div>
      <h1 className="text-2xl font-bold mb-6">Gestion des workflows</h1>
      <div className="card">
        {loading ? (
          <p>Chargement...</p>
        ) : workflows.length === 0 ? (
          <p className="text-gray-500">Aucun workflow trouvé.</p>
        ) : (
          <div className="space-y-4">
            {workflows.map((workflow) => (
              <div key={workflow.id} className="border rounded p-4">
                <h2 className="font-bold text-lg">{workflow.name}</h2>
                <p className="text-sm text-gray-600 mb-3">{workflow.description || 'Pas de description'}</p>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      <tr className="border-b">
                        <th className="text-left py-2">Ordre</th>
                        <th className="text-left py-2">Étape</th>
                        <th className="text-left py-2">Acteur</th>
                        <th className="text-left py-2">Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {(workflow.steps || []).map((step, idx) => (
                        <tr key={`${workflow.id}-${idx}`} className="border-b">
                          <td className="py-2">{idx + 1}</td>
                          <td>{step.name || '-'}</td>
                          <td>{step.actorType}:{step.actorValue}</td>
                          <td>{Array.isArray(step.actions) ? step.actions.join(', ') : '-'}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default WorkflowManagement;
